from __future__ import annotations

import dataclasses

import pytest

from boundary.config import PriceEntry
from boundary.ledger.prices import cost_usd
from boundary.types import Usage


def _field_names() -> list[str]:
    if dataclasses.is_dataclass(PriceEntry):
        return [f.name for f in dataclasses.fields(PriceEntry)]
    return list(getattr(PriceEntry, "model_fields"))


def _make_entry() -> PriceEntry:
    kwargs: dict[str, object] = {"input": 0.10, "output": 0.50}
    for name in _field_names():
        low = name.lower()
        if name in ("input", "output"):
            continue
        if "threshold" in low:
            kwargs[name] = 100_000
        elif "long" in low and "input" in low:
            kwargs[name] = 0.5
        elif "long" in low and "output" in low:
            kwargs[name] = 2.5
    return PriceEntry(**kwargs)  # type: ignore[arg-type]


def test_a_prompt_exactly_at_the_threshold_is_not_over_it() -> None:
    entry = _make_entry()
    at = Usage(input_tokens=100_000, output_tokens=1_000)
    assert cost_usd(at, entry) == pytest.approx((100_000 * 0.10 + 1_000 * 0.50) / 1e6)
    over = Usage(input_tokens=100_001, output_tokens=1_000)
    assert cost_usd(over, entry) == pytest.approx((100_001 * 0.5 + 1_000 * 2.5) / 1e6)
